'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const S = {language:'en',dict:{en:{},es:{}},user:null,data:null,admin:null,view:'home',mode:'personal',date:'',month:'',filter:{category:'',routine:'',status:'active',search:''},sharingTab:'with_me',shareFilter:{permission:'',category:'',owner:'',status:'',search:''},period:30,setupToken:null,resetToken:null,recoverySent:false,passwordReset:false,busy:false};
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t = (key,params={}) => {let v=S.dict[S.language]?.[key]??key; for(const [k,val] of Object.entries(params)) v=v.replaceAll(`{${k}}`,String(val)); return v;};
