 <section class="category-settings-section"><div class="section-heading"><div><h2>${t('chosen_categories')}</h2><p>${t('chosen_categories_hint')}</p></div></div>${S.data.categories.length?`<div class="category-grid">${S.data.categories.map(c=>{const count=S.data.habits.filter(h=>h.permission==='owner'&&Number(h.category_id)===Number(c.id)).length;return `<article class="category-card" style="--category-color:${esc(c.color)}"><button class="category-open" data-action="filter-category" data-id="${c.id}"><span class="category-icon">${icon(c.icon)}</span><h3>${esc(categoryName(c))}</h3><p>${t('habits_count',{count})}</p></button><div class="category-card-bottom">${badge(c.owner_user_id?'private':'global')}${c.owner_user_id?`<button class="text-btn" data-action="edit-category" data-id="${c.id}">${t('edit')}</button>`:`<button class="text-btn" data-action="leave-category" data-id="${c.id}">${t('remove_category_choice')}</button>`}</div></article>`;}).join('')}</div>`:empty('choose_your_categories','category_settings_intro')}</section>
